       "剧情后传巴拉乌广场，向西南到图勒斯道，经哈尔西恩麦田进格兰戴尔；到大拱门与拉德扎姆交谈。",
       "格兰戴尔周边集齐 12 名诺彭调查队（温温的任务要凑齐 11 人，最后在图图处补齐）；传封印岛看皇都，打两只原野波尼欧；回格兰戴尔打两只腿甲兽。",
       "<b>第３部 · 蒂兰实验室～采石场</b>：传天空桥到实验室；剧情后打加尔加与两名侵略者安多斯。",
       "回格兰戴尔，向入口民兵、城墙上层海恩塔、英雄安息处的萨尔加打听高纯度以太结晶；回大拱门找拉德扎姆。",
       "传图勒斯道，向北进法伊姆巷道，经肩胛枪地标到加马罗洼地，向西进禁声林地，到泽克尔玛尔加采石场。",
       "采石场蜘蛛对声音敏感，绕开或清掉；走右侧楼梯拿高纯度以太结晶；回拉德扎姆强化蒙纳多。",
       "雾兽袭击格兰戴尔：城墙 Boss、同伴岬蚂蚁王、回城墙恐蜥；获得强化蒙纳多。",
       "<b>第４部 · 皇都再访</b>：传皇都正门；格兰戴尔有新支线。",
       "上坡进皇宫，左转进传送器，这是不可返回点；进去前清完支线和收集。",
       "打雾之王第一阶段，看短剧情，再打第二阶段，通关。"
