  bestiaryMeta:{title:"珍稀种速查",tab:"珍稀种",note:"按区域列出本篇 157 只、相连的未来 20 只珍稀种，含等级、HP 与掉落。掉落只收素材、结晶、U 武器/装备和战技书；S 武器/防具是随机词条装备，不逐条列出。概率是各档宝箱的掉落率，普通宝箱出素材、稀有宝箱出结晶、金宝箱出 U 装备与战技书。",foot:"珍稀种只在特定地点、天气或时间出现，本表未收出现条件，按区域找即可，具体位置以游戏内地图为准。等级低于目标 3 级以上会严重减命中与伤害，先练级再刷。"},
