  fvMeta:{note:"43 条支线全部无时限、无二选一；任务名与 NPC 名保留英文（中文维基没有相连未来任务条目），步骤已按中文动作模板翻译，地点括号内保留英文原名。",foot:"相连未来的支线不计入主游戏 480/481 条任务统计，也不影响主线二选一。支线大多需要先推进格兰戴尔主线；诺彭调查队 12 人各对应一条支线（Tentoo 为剧情加入），完成后加入队伍并提供专属战技；成员表在「系统 → 诺彭调查队」。"},
